/**
 * Computes the de-duplicated set of labels that apply to a PR, given its
 * changed files and the configured rules. A file may match several rules
 * (contributing several labels); a label is included once no matter how
 * many files/rules produced it.
 */
export function assignLabels(files: string[], rules: Rule[]): string[] {
  const labels = new Set<string>();
  for (const rule of rules) {
    if (files.some((file) => matchesGlob(file, rule.pattern))) {
      labels.add(rule.label);
    }
  }
  return [...labels];
}

